{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain light background. Its body is covered in dense, long, shaggy brown fur that is darker on the legs and lighter on the muzzle and sides, with a sturdy bear-like build, thick neck, and broad torso. The dorsal surface from the shoulders to the rump is covered by a large, highly glossy, dark reddish-brown beetle-like exoskeleton, and a single large curved horn projects upward from the forehead. The animal stands on four thick legs with clawed paws, with a small furry tail visible at the rear, and its head has a bear-like snout, nose, eyes and small rounded ears.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with an elongated snout, black nose at the tip, small dark brown eyes, and lighter tan-brown fur on the muzzle, located at the front of the body facing right"
    ,
      "where": "front of body, in front of the neck and pronotal plate"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark reddish-brown to black curved horn with a small pointed side prong on the inner curve, smooth and shiny, tapering to a sharp tip",
      "where": "arising from the center of the forehead on top of the head, curving upward and slightly backward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur, with the right ear more visible than the left",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar legs covered in long shaggy dark brown fur, sturdy and bear-like",
      "where": "under the body, two forelegs under the chest and two hind legs under the hips, supporting the body in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with thick fur down to the toes and visible light brown to tan curved claws on each toe",
      "where": "at the bottom ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, rounded furry tail covered in brown fur",
      "where": "at the rear of the body on the left side, just above the hind legs, partially visible"
    },
    {
      "part": "shell",
      "looks_like": "large oval domed glossy shell with longitudinal ridges and fine horizontal striations, dark brown with reflective highlights, with a row of small circular openings along its lower edge where it meets the fur",
      "where": "covering the dorsal mid-back and rump, extending from behind the shoulder plate to above the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark reddish-brown pronotal plate with pointed lateral projections and a smooth shiny surface, with a raised central area",
      "where": "covering the shoulder and neck region directly behind the head and in front of the main oval shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
